            qudt:unit <http://qudt.org/vocab/unit/MilliM-PER-DAY> .
    FILTER(YEAR(?time) = 2002)
    BIND(MONTH(?time) AS ?month)
  }
}
GROUP BY ?month
ORDER BY DESC(?meanMonthlyPrecipitationRate)
LIMIT 1

